    {
      "step": 1,
      "tool": "temporal_grounder",
      "arguments": {
        "video_path": "VIDEO",
        "query": "chart titled JOB LOSS BY QUARTER showing job losses and years from 2007 to 2016"
      },
      "purpose": "Find the bounded interval where the relevant job-loss chart is on screen, rather than the earlier unrelated climate graph.",
      "depends_on": []
    },
    {
      "step": 2,
      "tool": "frame_retriever",
      "arguments": {
        "video_path": "VIDEO",
        "query": null,
        "timestamps": [
          "<STEP_1:segments[0].start>",
          "<STEP_1:segments[0].end>",
          "<STEP_1:segments[1].start>"
        ],
        "num_frames": 3
      },
      "purpose": "Sample candidate chart states from top localized intervals so the refiner can compare whether the chart is partial or fully updated before reading the peak year.",
      "depends_on": [
        1
      ]
    },
    {
      "step": 3,
      "tool": "chart_analyzer",
      "arguments": {
        "frame_path": "<STEP_2:frames>",
        "timestamp": null,
        "query": "job loss chart: identify which year has the highest job loss value and describe the peak point on the graph"
      },
      "purpose": "Read the chart structure and determine, per candidate frame, which year corresponds to the maximum job loss.",
      "depends_on": [
        2
      ]
    }
  ],
  "refinement_instructions": "Write the trace from scratch. First establish from temporal_grounder that the relevant evidence is the job-loss chart interval, not the earlier global-warming graph. Then use the frame_retriever timestamps and chart_analyzer frame-level results to select the candidate frame that actually shows the complete chart state needed for the question. Do not rely only on the chart_analyzer top-level summary if multiple frames differ; inspect frame_results and cite the frame whose plotted data clearly includes the peak. The rewritten trace should explicitly mention the chart title/topic, the identified peak year from the graph, and then map that verified year to the matching answer option. If the verified year contradicts the caption summary's rough description, prefer the chart_analyzer result from the selected fully rendered frame. Update the final answer accordingly."
}
